using Matrix2d = Eigen::Matrix<Real, 2, 2>;
using Matrix6d = Eigen::Matrix<Real, 6, 6>;
using Matrix3d = Eigen::Matrix<Real, 3, 3>;

// Helper: build 2x2 rotation matrix for angle phi
Matrix2d rotationMatrix2D(Real phi) {
    Real c = std::cos(phi);
    Real s = std::sin(phi);
    Matrix2d T;
    T << c, s,
        -s, c;
    return T;
