// Assemble 8x8 stiffness matrix for CQUAD4 using 4 triangular sub-elements (centroid-based)
Matrix8d computeCQUAD4Stiffness(
    const std::vector<Vector2d>& nodes, // 4 nodes: (0,0), (2,0), (2,1.5), (0,1.5)
    Real E, Real nu, Real t) {

    // Compute centroid
    Vector2d centroid = Vector2d::Zero();
    for (const auto& node : nodes) {
        centroid += node;
    }
    centroid /= 4.0;

    // Four triangles: (node_i, node_{i+1}, centroid), with wrap-around
    // Triangle I: nodes[0], nodes[1], centroid
    // Triangle II: nodes[1], nodes[2], centroid
    // Triangle III: nodes[2], nodes[3], centroid
    // Triangle IV: nodes[3], nodes[0], centroid
    std::vector<std::vector<int>> triangles = {
        {0, 1, -1}, // centroid is virtual node; we'll handle separately
        {1, 2, -1},
        {2, 3, -1},
        {3, 0, -1}
    };

    Matrix8d K = Matrix8d::Zero();

    // For each triangle, compute its 6x6 stiffness and add to global 8x8
    for (int tri_idx = 0; tri_idx < 4; ++tri_idx) {
        const auto& tri_nodes = triangles[tri_idx];
        const Vector2d& p1 = nodes[tri_nodes[0]];
        const Vector2d& p2 = nodes[tri_nodes[1]];
        const Vector2d& p3 = centroid; // centroid

        // Compute triangle orientation: angle of edge p1->p2
        Real dx = p2.x() - p1.x();
        Real dy = p2.y() - p1.y();
        Real phi = std::atan2(dy, dx);
        Matrix2d T = rotationMatrix2D(phi);

        // Build 6x6 rotation matrix: block-diagonal [T, T, T]
        Matrix6d T6 = Matrix6d::Zero();
        for (int i = 0; i < 3; ++i) {
            T6.block<2,2>(2*i, 2*i) = T;
        }

        // Material matrix D for plane stress (3x3, but we use only top-left 2x2 for membrane)
        // Full 3x3: D = (E/(1-nu^2)) * [1 nu 0; nu 1 0; 0 0 (1-nu)/2]
        Real denom = 1.0 - nu * nu;
        Real D00 = E / denom;
        Real D01 = E * nu / denom;
        Real D11 = E / denom;
        Real D22 = E * (1.0 - nu) / (2.0 * denom);

        // Area of triangle
        Real area = 0.5 * std::abs((p2.x() - p1.x()) * (p3.y() - p1.y()) - 
                                   (p3.x() - p1.x()) * (p2.y() - p1.y()));

        if (area <= 0.0) continue;

        // Coefficients for shape functions
        Real x1 = p1.x(), y1 = p1.y();
        Real x2 = p2.x(), y2 = p2.y();
        Real x3 = p3.x(), y3 = p3.y();

        Real detJ = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        if (std::abs(detJ) < 1e-15) continue;

        Real b1 = y2 - y3;
        Real b2 = y3 - y1;
        Real b3 = y1 - y2;
        Real c1 = x3 - x2;
        Real c2 = x1 - x3;
        Real c3 = x2 - x1;

        Real inv2A = 1.0 / (2.0 * area);
        Real factor = t * area * inv2A * inv2A;

        // Build 6x6 K_tri for this triangle (3 nodes, 2 DOF/node)
        Matrix6d K_tri = Matrix6d::Zero();

        // Loop over all 3x3 node pairs
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                Real b_i = (i == 0) ? b1 : (i == 1) ? b2 : b3;
                Real c_i = (i == 0) ? c1 : (i == 1) ? c2 : c3;
                Real b_j = (j == 0) ? b1 : (j == 1) ? b2 : b3;
                Real c_j = (j == 0) ? c1 : (j == 1) ? c2 : c3;

                // K(2*i, 2*j) += factor * (D00*b_i*b_j + D01*b_i*c_j + D01*c_i*b_j + D11*c_i*c_j)
                // Note: D is symmetric, so D01 appears twice
                K_tri(2*i, 2*j) += factor * (D00*b_i*b_j + D01*(b_i*c_j + c_i*b_j) + D11*c_i*c_j);
                // K(2*i, 2*j+1) += factor * (D00*b_i*c_j + D01*b_i*b_j + D01*c_i*c_j + D11*c_i*b_j)
                K_tri(2*i, 2*j+1) += factor * (D00*b_i*c_j + D01*(b_i*b_j + c_i*c_j) + D11*c_i*b_j);
                // K(2*i+1, 2*j) += factor * (D00*c_i*b_j + D01*c_i*c_j + D01*b_i*b_j + D11*b_i*c_j)
                K_tri(2*i+1, 2*j) += factor * (D00*c_i*b_j + D01*(c_i*c_j + b_i*b_j) + D11*b_i*c_j);
                // K(2*i+1, 2*j+1) += factor * (D00*c_i*c_j + D01*c_i*b_j + D01*b_i*c_j + D11*b_i*b_j)
                K_tri(2*i+1, 2*j+1) += factor * (D00*c_i*c_j + D01*(c_i*b_j + b_i*c_j) + D11*b_i*b_j);
            }
        }

        // Apply rotation: K_rot = T6^T * K_tri * T6
        Matrix6d K_rot = T6.transpose() * K_tri * T6;

        // Assemble into global 8x8 matrix
        // Local DOF mapping: local node i has DOFs [2*i, 2*i+1] → global DOFs [2*global_node, 2*global_node+1]
        // Triangle nodes: [0,1,2] -> global [tri_nodes[0], tri_nodes[1], centroid_index]
        // But centroid is not a global DOF — so only assemble contributions to corner nodes
        // So local nodes 0 and 1 map to corner nodes; local node 2 (centroid) is discarded (condensed)
        // However, standard approach: centroid is auxiliary; its DOFs are not in global matrix.
        // So we only assemble blocks for local nodes 0 and 1 (the corners).
        // Thus, only 4x4 submatrix of K_rot (rows/cols 0-3) is assembled.
        for (int i_local = 0; i_local < 2; ++i_local) {
            int i_global = tri_nodes[i_local];
            for (int j_local = 0; j_local < 2; ++j_local) {
                int j_global = tri_nodes[j_local];
                for (int di = 0; di < 2; ++di) {
                    for (int dj = 0; dj < 2; ++dj) {
                        int i_dof = 2 * i_global + di;
                        int j_dof = 2 * j_global + dj;
                        K(i_dof, j_dof) += K_rot(2*i_local + di, 2*j_local + dj);
                    }
                }
            }
        }
        // Also assemble cross terms between corner and centroid? No — centroid DOFs are condensed out.
        // So skip local node 2 (index 2) entirely.
    }

    return K;
}

